{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid acid with the same conjugated tetraene and trimethylcyclohexene core, has an absolute oral bioavailability of approximately 60% (range 36–95%) after a 50 mg oral dose with food compared with IV infusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Acitretin administered as a 50 mg aqueous microsuspension showed a mean oral bioavailability of 72% versus IV infusion in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a highly lipophilic retinoid ester, has an absolute oral bioavailability of about 40% compared with IV administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin has a systemic bioavailability of 40% at a dosage of 1 mg/kg/day based on multiple-dose pharmacokinetic data.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Oral all-trans retinoic acid bioavailability was estimated at no more than 25–30% in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "13-cis retinoic acid was described as having low absolute bioavailability with gut degradation, but no numeric value below 20% was established and quantitative retinoid estimates are higher.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoid amide (fenretinide-like). Transferable retinoid acid/ester analogs consistently show oral bioavailability around 40–60%, with even the lowest quantitative retinoid estimates at 25–30%, supporting F ≥ 20%. No affirmative evidence indicates F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is provided.",
    "The effect of the p-hydroxyanilide amide modification on absorption, solubility, and first-pass metabolism relative to retinoic acid/acitretin/etretinate is not directly evidenced.",
    "Some records in the evidence set are mismatched to their listed structures (e.g., triamterene, topotecan, vinorelbine) and were not used as retinoid evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

